SELECT d.*, cp.id as 'project.id', cp.name as 'project.name', cp.short_name as 'project.short_name', cp.serial_number as 'project.serialNumber', m.id as 'monomer.id', m.name as 'monomer.name', u.name as createUserName FROM tech_drawing as d LEFT JOIN sys_user as u ON u.id = d.create_user_id left join contract_project as cp on d.project_id = cp.id and cp.bool_delete_enum = 0 left join plan_monomer as m on d.monomer_id = m.id and m.bool_delete_enum = 0 where d.bool_delete_enum = 0 and u.bool_delete_enum = 0 and cp.bool_delete_enum = 0
AND d.project_id = #{projectId}
AND d.monomer_id = #{monomerId}
AND d.serial_number LIKE CONCAT('%',#{serialNumber},'%')
AND d.file_name LIKE CONCAT('%',#{fileName},'%')
AND d.data_type = #{dataType}
AND d.product_type = #{productType}
AND d.project_type = #{projectType}

choose.when:
SELECT mon.id monomerId, mon.`name` monomerName, #{projectId} projectId, #{productType} productType, #{dataType} dataType, IFNULL( SUM( art.quantity ), 0 ) quantity , IFNULL( SUM( IF ( ISNULL(dra.id ) , 0, art.quantity )), 0 ) drawingQuantity, IFNULL( SUM( IF ( ISNULL(weld.id ) , 0, art.quantity )), 0 ) productWeldQuantity FROM plan_monomer mon
LEFT JOIN tech_artifact art ON mon.id = art.monomer_id AND art.bool_delete_enum = 0
LEFT JOIN tech_assemble art ON mon.id = art.monomer_id AND art.bool_delete_enum = 0
LEFT JOIN tech_machine_part art ON mon.id = art.monomer_id
AND art.bool_delete_enum = 0 AND art.steel_plate_type_enum = #{steelPlateTypeEnum}
AND art.bool_delete_enum = 0 AND art.steel_plate_type_enum in (1, 2)
LEFT JOIN tech_capp_craft_card_product_welding weld ON weld.monomer_id = mon.id LEFT JOIN tech_drawing dra ON dra.monomer_id = mon.id
AND art.initial_serial_number = dra.serial_number
AND dra.serial_number = art.serial_number
AND dra.bool_delete_enum = 0 AND dra.data_type=#{dataType}
AND dra.product_type = #{productType}
AND dra.product_type = #{productType}
AND dra.product_type is null
AND dra.product_type = #{productType}
WHERE mon.bool_delete_enum = 0 AND mon.project_id = #{projectId}
AND mon.id = #{monomerId}
GROUP BY mon.id ORDER BY monomerId ASC

SELECT

    art.initial_serial_number serialNumber


    art.serial_number serialNumber

FROM
plan_monomer mon

    LEFT JOIN tech_artifact art ON mon.id = art.monomer_id AND art.bool_delete_enum = 0


    LEFT JOIN tech_assemble art ON mon.id = art.monomer_id AND art.bool_delete_enum = 0


    LEFT JOIN tech_machine_part art ON mon.id = art.monomer_id
    
        AND art.bool_delete_enum = 0 AND art.steel_plate_type_enum = #{steelPlateTypeEnum}
    
    
        AND art.bool_delete_enum = 0 AND art.steel_plate_type_enum in (1, 2, 4)
    

left join plan_area area on art.area_id = area.id and area.bool_delete_enum = 0
INNER JOIN tech_drawing dra ON dra.monomer_id = mon.id
AND dra.bool_delete_enum = 0 AND dra.data_type=#{dataType}

    AND dra.serial_number = art.initial_serial_number


    AND dra.serial_number = art.serial_number


    AND dra.product_type = #{productType}


    AND dra.product_type = #{productType}


    AND dra.product_type is null


    AND dra.product_type = #{productType}

WHERE
mon.bool_delete_enum = 0
AND mon.project_id = #{projectId}

    and mon.id = #{monomerId}


    and art.area_id = #{areaId}


    and art.area_batch_id = #{areaBatchId}

SELECT a.projectId projectId, a.monomer_id monomerId, mon.`name` monomerName, a.area_id areaId, are.`name` areaName, #{productType} productType, #{dataType} dataType, a.productId productId, a.quantity quantity, a.serialNumber serialNumber, a.specification specification, IF(COUNT( dra.id )=0,0,1) sign FROM ( SELECT art.specification specification, art.project_id projectId, #{productType} productType, art.area_id, art.monomer_id, IFNULL( art.quantity, 0 ) quantity, art.id productId,
art.initial_serial_number serialNumber
art.serial_number serialNumber
FROM
tech_artifact art
tech_assemble art
tech_machine_part art
WHERE
art.project_id = #{projectId}
AND art.steel_plate_type_enum = #{steelPlateTypeEnum} AND art.product_classification_enum = 8
AND art.steel_plate_type_enum in (1,2) AND art.product_classification_enum = 8
AND art.monomer_id = #{monomerId}
and art.area_id = #{areaId}
and art.area_batch_id = #{areaBatchId}
AND art.serial_number LIKE concat('%', #{serialNumber}, '%')
AND art.bool_delete_enum = 0 ) a LEFT JOIN tech_drawing dra ON dra.bool_delete_enum = 0 AND dra.serial_number = a.serialNumber
AND dra.product_type = #{productType}
AND dra.product_type = #{productType}
AND dra.product_type IS NULL
AND dra.product_type = #{productType}
AND dra.data_type=#{dataType}
AND dra.monomer_id = #{monomerId}
AND dra.area_id = #{areaId}
LEFT JOIN plan_monomer mon ON a.monomer_id=mon.id AND mon.bool_delete_enum=0 LEFT JOIN plan_area are ON a.area_id=are.id AND are.bool_delete_enum=0 LEFT JOIN sys_user su ON su.id=dra.create_user_id and su.bool_delete_enum=0
su.name LIKE concat('%', #{userName}, '%')
and (dra.serial_number IS NOT NULL
or !(RIGHT(a.serialNumber, 1) BETWEEN '0' AND '9')
)
and !(dra.serial_number IS NOT NULL
or !(RIGHT(a.serialNumber, 1) BETWEEN '0' AND '9')
)
GROUP BY a.serialNumber, a.productId ORDER BY sign ASC, monomerId ASC, productId ASC, areaId ASC

mapper.select:
SELECT dra.id id, dra.serial_number serialNumber, dra.data_type dataType, dra.create_user_id createUserId, dra.update_time updateTime, dra.create_time createTime, sse.`name` createUserName FROM tech_drawing dra LEFT JOIN sys_user sse ON sse.id = dra.create_user_id WHERE dra.bool_delete_enum = 0
AND dra.monomer_id = #{monomerId}
AND dra.data_type = #{dataType}
AND dra.product_type = #{productType}
AND dra.product_type = #{productType}
AND dra.product_type = #{productType}
AND dra.product_type IS NULL
AND dra.serial_number IN
#{item}
AND dra.area_id = #{areaId}
ORDER BY dra.update_time DESC

SELECT a.projectId projectId , a.monomer_id monId, mon.`name` monName, a.area_id areaId, are.`name` areaName, #{productType} productType, #{dataType} dataType, a.productId productId, a.quantity quantity, a.serialNumber serialNumber, a.specification specification, a.`NAME`, IF(COUNT( dra.id )=0,0,1) sign FROM ( SELECT art.specification specification, art.project_id projectId, #{productType} productType, art.area_id, art.monomer_id, IFNULL( art.quantity, 0 ) quantity, art.id productId, art.serial_number serialNumber,
class.classification_name name
class.name name
class.name name
FROM
tech_artifact art LEFT JOIN sys_structure_classification class ON class.bool_delete_enum=0 AND art.structure_class_id=class.id
tech_assemble art LEFT JOIN sys_assemble_config class ON class.bool_delete_enum=0 AND art.assemble_config_id=class.id
tech_machine_part art LEFT JOIN sys_steel_classification class ON class.bool_delete_enum=0 AND class.id=art.steel_id
WHERE
art.project_id = #{projectId}
AND art.monomer_id = #{monomerId}
AND art.area_id=#{areaId}
AND art.serial_number LIKE concat('%', #{serialNumber}, '%')
AND art.bool_delete_enum = 0 ) a LEFT JOIN process_instruction_link dra ON dra.bool_delete_enum = 0 AND dra.serial_number = a.serialNumber
AND dra.product_type = #{productType}
AND dra.data_type=#{dataType}
AND dra.monomer_id = #{monomerId}
AND dra.drawing_id = #{drawingid}
LEFT JOIN plan_monomer mon ON a.monomer_id=mon.id AND mon.bool_delete_enum=0 LEFT JOIN plan_area are ON a.area_id=are.id AND are.bool_delete_enum=0 GROUP BY a.serialNumber, a.productId ORDER BY sign asc

SELECT par.id productId, dra.id drwaingId, dra.picture_path picturePath FROM bridge_tech_machine_part par LEFT JOIN tech_drawing dra ON par.monomer_id = dra.monomer_id AND par.serial_number = dra.serial_number AND dra.product_type=4 AND dra.data_type = 2 AND dra.bool_delete_enum=0 WHERE par.bool_delete_enum=0
AND par.id IN
#{item}

